{
  "name": "mimo-free-opencode-plugin",
  "version": "0.2.1",
  "description": "OpenCode provider plugin for Xiaomi MiMo Code's free mimo-auto model — anonymous, keyless, no account required",
  "type": "module",
  "dependencies": {
    "undici": "^6"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./runtime": {
      "import": "./dist/runtime.js",
      "types": "./dist/runtime.d.ts"
    }
  },
  "bin": {
    "mimo-free-opencode-plugin": "./cli.js"
  },
  "files": [
    "dist",
    "cli.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "test": "node --import tsx --test \"src/**/*.test.ts\"",
    "clean": "node -e \"const fs=require('fs');if(fs.existsSync('dist'))fs.rmSync('dist',{recursive:true});\"",
    "check:exports": "node --input-type=module -e \"import('./dist/index.js').then((m)=>{if(typeof m.default!=='function'){throw new Error('Default export must be a function');}for(const [key,value] of Object.entries(m)){if(typeof value!=='function'){throw new Error('Root export '+key+' must be a function to satisfy plugin loader constraints');}}})\"",
    "prepublishOnly": "npm run clean && npm run build && npm run check:exports"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "provider",
    "auth",
    "mimo",
    "mimo-code",
    "xiaomi",
    "free",
    "openai-compatible"
  ],
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/anshuman852/mimo-free-opencode-plugin.git"
  },
  "homepage": "https://github.com/anshuman852/mimo-free-opencode-plugin#readme",
  "bugs": {
    "url": "https://github.com/anshuman852/mimo-free-opencode-plugin/issues"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "*",
    "@types/node": "^20.0.0",
    "tsx": "^4.23.0",
    "typescript": "^5.0.0"
  },
  "engines": {
    "node": ">=20.0.0"
  }
}
